import type { SystemStyleObject } from '@chakra-ui/react';
import { breakpoints } from 'app/theme/foundation';
const GRID_CARD_GAP_DESKTOP = '6rem'; // 96px — confirmed Figma value, checked at two independent sources (40000301:11694 "Product Card Group" master, Size=Desktop/Display=4, node 40000307:12446; and the page-level instance 3332:35655). No --zimm-scale-* equivalent (nearest neighbours: named scale 5xl=80px / 6xl=128px; numeric alias 1600=64px jumps straight to 3500=140px) — pending promotion to foundation/spacing.ts or sizes.ts by the UI designer.
const GRID_COLUMNS_BASE = 2; // Mobile only (below breakpoints.md) — Marcel, 2026-09-08.
const GRID_COLUMNS_TABLET = 3; // breakpoints.md up, below breakpoints.xl — Marcel, 2026-09-08.
const GRID_COLUMNS_DESKTOP = 4; // breakpoints.xl and up — confirmed (Figma nodes cited in the docblock above).
const TABLET_UP_QUERY = `@media (min-width: ${breakpoints.md})`; // 768px
const DESKTOP_UP_QUERY = `@media (min-width: ${breakpoints.xl})`; // 1280px — the confirmed 4-up/288px reading itself comes from a 1440px Figma frame, inside this tier.
const GRID_CONTENT_MAX_WIDTH_DESKTOP = '90rem'; // 1440px = (288px x 4 cards) + (96px x 3 gaps)
const HEADER_PADDING_INLINE = 'var(--zimm-scale-800)'; // 32px -- Tablet/Mobile
const HEADER_PADDING_BLOCK = 'var(--zimm-scale-500)'; // 20px -- Tablet/Mobile
const HEADER_PADDING_DESKTOP = 'var(--zimm-scale-1000)'; // 40px -- Desktop, all four sides
export const ZimmRecentlyViewedGrid = {
  parts: ['container', 'header', 'grid'],
  baseStyle: (): Record<string, SystemStyleObject> => ({
    container: {
      width: '100%',
      marginInline: 'auto',
      [DESKTOP_UP_QUERY]: {
        maxWidth: GRID_CONTENT_MAX_WIDTH_DESKTOP,
      },
    },
    header: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      paddingInline: HEADER_PADDING_INLINE,
      paddingBlock: HEADER_PADDING_BLOCK,
      [DESKTOP_UP_QUERY]: {
        paddingInline: HEADER_PADDING_DESKTOP,
        paddingBlock: HEADER_PADDING_DESKTOP,
      },
    },
    grid: {
      display: 'grid',
      width: '100%',
      gridTemplateColumns: `repeat(${GRID_COLUMNS_BASE}, minmax(0, 1fr))`,
      columnGap: 'var(--zimm-scale-1000)', // 40px — Mobile
      rowGap: 'var(--zimm-scale-1600)', // 64px
      [TABLET_UP_QUERY]: {
        gridTemplateColumns: `repeat(${GRID_COLUMNS_TABLET}, minmax(0, 1fr))`,
        columnGap: 'var(--zimm-scale-5xl)', // 80px
      },
      [DESKTOP_UP_QUERY]: {
        gridTemplateColumns: `repeat(${GRID_COLUMNS_DESKTOP}, minmax(0, 1fr))`,
        columnGap: GRID_CARD_GAP_DESKTOP,
      },
    },
  }),
};

=== useRecentlyViewedRailVisibleCount ===
import { useMediaQuery } from '@chakra-ui/react';
import { breakpoints } from 'app/theme/foundation';
import { RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS, RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT } from 'app/constants';

/**
 * SFCC-83 — resolves how many Recently Viewed cards should be visible for the current real
 * breakpoint. Fixes a real, live-confirmed bug (2026-09-10): `useBreakpointValue` can only switch
 * at this site's own registered Chakra breakpoints (`base`/`sm`/`md`/`lg`/`xl`/`2xl`), but the
 * rail's own card-width styling (`zimmRecentlyViewedRail.css.ts`'s `DESKTOP_UP_QUERY`) switches to
 * Desktop sizing at 1024px — this component's own real Figma Desktop threshold, not this site's
 * shared `breakpoints.xl` (1280px). Calling `useBreakpointValue(RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS)`
 * directly (the previous approach) meant the item-count cap only ever stepped to 5 at 1280px,
 * leaving a 1024–1280px gap where the card row was already styled for 5 slots but only 3 cards
 * were allowed to render — see `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS`'s own correction note
 * (`app/constants/index.ts`) for the full incident.
 *
 * Two raw `useMediaQuery` checks, not `useBreakpointValue`, because the Desktop threshold this
 * needs to match (1024px) has no corresponding entry in this site's registered breakpoint scale
 * to key an object against — `breakpoints.md` (768px) still correctly matches both this site's
 * shared value and the rail's own Tablet start, so only the Desktop half needs the raw-query
 * treatment. Checked widest-first (Desktop, then Tablet) since both are plain `min-width` queries
 * that both remain true well past their own threshold — a real 1440px viewport matches both, and
 * only the order of these checks (not a mutually-exclusive range) picks the right one.
 *
 * SSR-safe by the same construction `useBreakpointValue` already relied on: both media queries
 * default to `false` before the client-side match resolves, so this correctly falls through to
 * `RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base` (the smallest/mobile count) on the very first
 * render, matching this hook's two callers' own prior documented fallback behaviour.
 *
 * @returns The number of cards the rail should render/cap to at the current real breakpoint.
 */
export const useRecentlyViewedRailVisibleCount = (): number => {
  const [isTabletUp] = useMediaQuery(`(min-width: ${breakpoints.md})`);
  const [isDesktop] = useMediaQuery(`(min-width: ${RECENTLY_VIEWED_RAIL_DESKTOP_BREAKPOINT})`);

  if (isDesktop) return RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.xl;
  if (isTabletUp) return RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.md;
  return RECENTLY_VIEWED_RAIL_VISIBLE_COUNTS.base;
};

1	import React, { useEffect, useRef, useState } from 'react';
2	import { AspectRatio, Image, chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import DynamicImage from '@salesforce/retail-react-app/app/components/dynamic-image';
5	import useIntersectionObserver from '@salesforce/retail-react-app/app/hooks/use-intersection-observer';
6	import { ZimmButton } from '../zimmButton';
7	import { GALLERY_ITEM_ASPECT_RATIO } from './zimmMediaTile.css';
8	import { buildDisImageSrc } from 'app/utils/buildDisImageSrc';
9	
10	/**
11	 * SFCC image-loading/LCP follow-up (2026-09-20) — how far ahead of the viewport a non-eager tile
12	 * starts loading for real, overriding the browser's own native `loading="lazy"` heuristic (which
13	 * still ships as the SSR/no-JS baseline — see the `ref`/`useEffect` wiring below). 200px sits in
14	 * the commonly-recommended real-world range (50–300px: MDN's Intersection Observer guidance,
15	 * `media-delivery.com`'s "Advanced IntersectionObserver Patterns for Media") — enough lead time
16	 * for network+decode to finish before a typical scroll reaches the tile, without the callback/
17	 * memory overhead a much larger margin costs (more elements considered "intersecting" at once).
18	 *
19	 * Known, accepted trade-off: Chrome's own native `loading="lazy"` heuristic is adaptive — it uses
20	 * a SMALLER lookahead on slow connections specifically to avoid spending scarce bandwidth on
21	 * images that might never be scrolled to. A fixed 200px is not adaptive the same way, so on a
22	 * genuinely slow connection this can start a fetch earlier than Chrome itself would have judged
23	 * wise, competing with other still-in-flight critical resources. Accepted here because the goal is
24	 * a predictable, non-network-dependent scroll experience (this session's own brief: "not have to
25	 * wait for images to load as I scroll"), not to out-guess Chrome's own heuristic — revisit if this
26	 * ever shows up as a real regression on throttled connections.
27	 *
28	 * `ZimmProductCardMedia` (ui-kits/molecules) uses this exact same value — kept as its own local
29	 * constant there rather than imported from here, deliberately: importing this file for just the
30	 * constant would also pull in this atom's `ZimmButton`/video-controls dependency chain, coupling
31	 * an unrelated component tree to a single string literal. See that file's own note next to its
32	 * copy of this constant.
33	 */
34	const EARLY_LOAD_ROOT_MARGIN = '200px';
35	
36	/** Same shape base SFCC's `DynamicImage`/`getResponsivePictureAttributes` accept. */
37	export type ZimmMediaTileWidths = (number | string)[] | Record<string, number | string>;
38	
39	const messages = defineMessages({
40	  play: { id: 'product_gallery.video.play', defaultMessage: 'Play video' },
41	  pause: { id: 'product_gallery.video.pause', defaultMessage: 'Pause video' },
42	  mute: { id: 'product_gallery.video.mute', defaultMessage: 'Mute video' },
43	  unmute: { id: 'product_gallery.video.unmute', defaultMessage: 'Unmute video' },
44	});
45	
46	const ZIMM_MEDIA_TILE_RECIPE = 'ZimmMediaTile';
47	
48	export type ZimmGalleryPhotoItem = {
49	  kind: 'photo';
50	  src: string;
51	  alt: string;
52	};
53	
54	export type ZimmGalleryVideoItem = {
55	  kind: 'video';
56	  /**
57	   * Poster frame shown in place of real playback. No product video data source exists yet —
58	   * SFCC-188 ("PDP – Product Video in Gallery") is blocked on a content-modelling workshop for
59	   * how video is stored on the product and ordered in the gallery. This renders the positional
60	   * slot and a real, keyboard-operable control shell (play/pause, mute) ready for SFCC-188 to
61	   * wire an actual source into, but the controls only toggle local UI state today.
62	   */
63	  posterSrc: string;
64	  posterAlt: string;
65	};
66	
67	export type ZimmGalleryMediaItem = ZimmGalleryPhotoItem | ZimmGalleryVideoItem;
68	
69	export type ZimmMediaTileProps = {
70	  item: ZimmGalleryMediaItem;
71	  /** Skips `loading="lazy"` — pass for the item that should load with LCP priority. */
72	  eager?: boolean;
73	  /**
74	   * SFCC-731 AC 19 — this tile's own real rendered width per breakpoint (px/vw, or a single
75	   * value), e.g. `{base: '100vw', lg: 902}`. The atom has no layout context of its own — it's
76	   * reused inside full-bleed stacked items, 2/4-up grid cells, and a fluid mobile carousel, each
77	   * a different real width — so each caller supplies its own. When omitted, the image renders
78	   * at its raw source resolution with no responsive `srcset` (this atom's previous behaviour).
79	   */
80	  widths?: ZimmMediaTileWidths;
81	  /** DIS `q` param (0-100), forwarded to `buildDisImageSrc`. Only used when `widths` is given. */
82	  quality?: number;
83	};
84	
85	/**
86	 * Atom — a single photo or video gallery tile's own visual content: aspect-ratio box, the image
87	 * itself (with a load-failure fallback), and — for a video item — its play/pause/mute control
88	 * shell. No interactive "open gallery" trigger behaviour lives here; that's the caller's
89	 * concern (see ZimmProductGallery's sibling `triggerOverlay` button and ZimmGalleryOverlay's
90	 * plain scrollable stack).
91	 *
92	 * Reused across the PDP's default gallery state (ZimmProductGallery) and its expanded/overlay
93	 * state (ZimmGalleryOverlay, SFCC-731 AC 12-25) so the load-failure and aspect-ratio handling
94	 * can't drift between the two.
95	 */
96	export const ZimmMediaTile = ({ item, eager = false, widths, quality }: ZimmMediaTileProps) => {
97	  const intl = useIntl();
98	  const styles = useMultiStyleConfig(ZIMM_MEDIA_TILE_RECIPE, {});
99	  // No real playback source yet (see ZimmGalleryVideoItem) — these toggle local UI state only,
100	  // ready for SFCC-188 to wire a real <video>/Vimeo source behind.
101	  const [playing, setPlaying] = useState(false);
102	  const [muted, setMuted] = useState(true);
103	  // SFCC-731 AC 21 — a failed load keeps the aspect-ratio box (no layout shift) with a neutral
104	  // fill instead of the browser's broken-image icon. Tracks the SOURCE that failed, not a plain
105	  // boolean — a tile is reused at the same list position across renders (index-keyed), so a
106	  // plain boolean would keep showing the fallback for a brand-new, valid source after a
107	  // variation swap replaces a previously-failed one (CodeRabbit, PR #81).
108	  const [erroredSrc, setErroredSrc] = useState<string | null>(null);
109	  const src = item.kind === 'photo' ? item.src : item.posterSrc;
110	  const alt = item.kind === 'photo' ? item.alt : item.posterAlt;
111	  const hasError = erroredSrc === src;
112	
113	  // SFCC image-loading/LCP follow-up (2026-09-20) — `imgRef` is attached to the real rendered
114	  // <img> in both non-error branches below (via `imageProps.ref` for the DynamicImage branch,
115	  // `ref` directly for the plain-`<Image>` branch — both are `forwardRef`-based, so a `ref` key
116	  // spread through `imageProps` resolves the same as a literal one). `useIntersectionObserver` is
117	  // the base SFCC hook already used elsewhere in this codebase (`recommended-products/index.tsx`)
118	  // — no new hook needed. `useOnce: true` disconnects after the first trigger; this never resets.
119	  const imgRef = useRef<HTMLImageElement>(null);
120	  const isNearViewport = useIntersectionObserver(imgRef, { rootMargin: EARLY_LOAD_ROOT_MARGIN, useOnce: true });
121	  useEffect(() => {
122	    // `!eager` guard: an eager tile already renders `loading="eager"` from the start — nothing to
123	    // flip. `setAttribute`, not `imgRef.current.loading = 'eager'` — confirmed live (2026-09-20)
124	    // that the IDL-property assignment does NOT reliably reflect to the actual content attribute
125	    // in every environment (jsdom's `HTMLImageElement.loading` setter silently no-ops on the real
126	    // attribute, so `toHaveAttribute` never sees the change even though the in-memory JS property
127	    // itself updates) — `setAttribute` is the universally-correct DOM primitive regardless of how
128	    // completely a given environment implements newer IDL reflection, and real browsers honour it
129	    // identically to the property setter for triggering an eager fetch. Mutates the DOM directly
130	    // (not React state) since this is a one-way, one-time upgrade of an already-rendered,
131	    // unchanged-from-React's-perspective `lazy` prop — see this file's own note above on why
132	    // React never fights this (its own JSX-authored value is untouched, so reconciliation has
133	    // nothing to reapply).
134	    if (!eager && isNearViewport && imgRef.current) {
135	      imgRef.current.setAttribute('loading', 'eager');
136	    }
137	  }, [eager, isNearViewport]);
138	
139	  // SFCC-731 AC 19 — responsive DIS srcset when the caller knows its own real rendered width
140	  // (`widths`); otherwise the raw source, unchanged from this atom's previous behaviour. Shared
141	  // between the photo and video-poster branches below so they can't drift from each other.
142	  const image = hasError ? (
143	    <chakra.div __css={styles.mediaFallback} role="img" aria-label={alt} aria-hidden={alt === '' || undefined} />
144	  ) : widths ? (
145	    <DynamicImage
146	      as={Image}
147	      src={buildDisImageSrc(src, quality)}
148	      widths={widths}
149	      imageProps={{
150	        ref: imgRef,
151	        alt,
152	        loading: eager ? 'eager' : 'lazy',
153	        width: '100%',
154	        height: '100%',
155	        objectFit: 'cover',
156	        onError: () => setErroredSrc(src),
157	      }}
158	      // AspectRatio's own CSS (`& > *:not(style)`) sizes DynamicImage's outer Box correctly,
159	      // since that Box is AspectRatio's direct child — but `<picture>` (DynamicImage's own
160	      // markup, one level further in, not exposed as a prop) is `display: inline` by default
