} from '../../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../../components/ui-kits/molecules/zimmSizeChipGroup';
import { sortImagesBySequence, resolveFallbackColour, toGalleryAlt } from '../../utils/productCardMappingHelpers';

// This mapper is PLP-only by design, so it returns the narrowed shape directly rather than the
// full `ZimmProductCardProps` union — letting a caller pass the result straight to a
// PLP-typed component (like this page's own `ProductListCard`) with no re-narrowing needed.
type ProductListCardResult = ZimmProductCardBaseProps & ZimmProductCardPlpVariation;

/**
 * `c_productBadges` is a custom SFCC attribute (SFCC-225's own already-merged SCAPI hook) with no
 * typed field on the base SDK's `ProductSearchHit` — it only reaches this shape via that type's
 * own `{[key: string]: any}` index signature. Narrowed here to the one shape this mapper reads,
 * rather than trusting `any` at every call site.
 */
export type ProductListSearchHit = ShopperSearchTypes.ProductSearchHit & {
  c_productBadges?: Array<{ productBadge?: string }>;
};

type RawImage = { alt?: string; disBaseLink?: string; link?: string };

const toCardImage = (image: RawImage | undefined): ZimmProductCardImage | undefined => {
  const src = image?.disBaseLink ?? image?.link;
  if (!src) return undefined;
  return { src, alt: toGalleryAlt(image?.alt) };
};

/** The correctly-sized product image view — never serve an arbitrary-sized image at thumbnail
 *  size (AGENTS.md's image-sizing guidance). Same constant, same reasoning, as
 *  `recentlyViewedFullHistoryCard.ts`'s own `MEDIUM_VIEW_TYPE`. */
const MEDIUM_VIEW_TYPE = 'medium';

/** The variation-attribute id `filterImageGroups` matches an image group's colour against —
 *  named per conventions.md's no-magic-strings rule. */
const COLOUR_VARIATION_ATTRIBUTE_ID = 'color';

/** The one shape this mapper reads off a `filterImageGroups` result — that function ships from
 *  an untyped base-SFCC module (`@salesforce/retail-react-app` has no types for this subpath, see
 *  `RawImage`'s own comment above for the same reasoning), so this documents an assumed shape
 *  rather than letting `any` propagate silently. */
type ImageGroupShape = { images?: RawImage[] };

/**
 * Sorts by the merchandiser-assigned sequence number baked into each image's own filename
 * (e.g. `.../images/1.4673ts251.gvscp.guava-seascape.jpg` → `1`) — 2026-09-09, closing a real,
 * live bug: the array order `filterImageGroups` hands back is NOT guaranteed to match this
 * sequence. Confirmed live on two real products (`4673TS251`, `5487S24`): a newly-published,
 * colour-tagged image group can come back as `[2, 1, 3, 4, ...]` rather than ascending order,
 * which silently swapped this variation's primary/hover images — the flat-lay product shot
 * (always image `1`, confirmed by direct visual inspection on two real products,
 * `4673TS251`/`8637DS241`) showed on hover instead of by default, with the on-model shot (image
 * `2`) showing as primary. Sorting by this number restores the intended sequence regardless of
 * whatever order the API happens to return.
 *
 * Shared with `recentlyViewedCard.ts` and `recentlyViewedFullHistoryCard.ts` — see
 * `productCardMappingHelpers.ts`'s own docblock for why a shared primitive rather than three
 * separate copies (all three had drifted onto the identical non-transitive-comparator bug,
 * CodeRabbit 2026-09-10).
 */
const sortByImageSequence = (images: ZimmProductCardImage[]): ZimmProductCardImage[] =>
  sortImagesBySequence(images, (image) => image.src);

/**
 * Resolves which real colour this hit's card should show images for — 2026-09-08, closing a
 * real bug: `selectGalleryImages` below used to pick "whichever image group has the most
 * images," with no colour or viewtype awareness at all, so a multi-colour product could show a
 * different colour's photos in its gallery than the one the store itself picked as
 * representative. Two tries, in order:
