  const images = (groups[0]?.images ?? [])
    .map(toCardImage)
    .filter((image): image is ZimmProductCardImage => Boolean(image));

  return sortByImageSequence(images);
};

/**
 * Picks this hit's gallery from the colour-scoped image list above — matches
 * `ZimmProductCardMedia`'s own "no gallery" contract for 0 or 1 images (returns `undefined`,
 * never a 1-length array).
 */
export const selectGalleryImages = (hit: ProductListSearchHit): ZimmProductCardImage[] | undefined => {
  const images = selectColourScopedImages(hit, resolveRepresentativeColour(hit));
  return images.length > 1 ? images : undefined;
};

/**
 * Reads the "size" variation attribute (if this hit has one) into the shape
 * `ZimmSizeChipGroup` expects. `orderable` on each value already reflects real stock per that
 * specific size, so it maps directly to `isDisabled` with no extra lookup needed.
 */
export const selectSizeChipValues = (hit: ProductListSearchHit): ZimmSizeChipValue[] => {
  const sizeAttribute = hit.variationAttributes?.find((attr) => attr.id === 'size');
  return (sizeAttribute?.values ?? []).map((value) => ({
    value: value.value,
    label: value.name ?? value.value,
    isDisabled: value.orderable === false,
  }));
};

/** What `resolveOrderableVariant` resolves a selected size chip value to — the real, orderable
 *  SKU for that specific size, not the master/represented-product id this hit otherwise defaults
 *  to. `price` is the variant's own (`ShopperSearchTypes.Variant`'s own field, confirmed real via
 *  a live product-detail check, 2026-09-08), which can genuinely differ from the hit's own flat
 *  `price` across sizes (e.g. plus sizes priced higher) — callers should prefer this over the
 *  hit's own price once a variant has been resolved. */
export type ResolvedVariant = {
  productId: string;
  price: number | undefined;
  orderable: boolean;
};

/**
 * Resolves a selected size CHIP VALUE to its real orderable variant — added 2026-09-08 (Gap 3:
 * "size-aware Add to Bag" was previously cosmetic; selecting a chip never changed what got added
 * to the bag at all). Confirmed live against product `4673TS251`: `hit.variants` is real and
 * populated (`expand: [...,'variations']`, already requested by this page's own search call),
 * each entry carrying its own real `productId` (e.g. `4673TS251GVSCP0P`) keyed by
 * `variationValues.size` (e.g. `'0P'`) — exactly the lookup this function performs.
 *
 * Returns `null` when there is no matching variant at all (no `variants` array, or no entry
 * whose `variationValues.size` equals `sizeValue`) — callers are expected to fall back to this
 * hit's own default `representedProduct`/`productId` resolution in that case, the same default
 * that already existed before size-aware add-to-bag was ever selectable.
 */
export const resolveOrderableVariant = (hit: ProductListSearchHit, sizeValue: string): ResolvedVariant | null => {
  const variant = hit.variants?.find((candidate) => candidate.variationValues?.size === sizeValue);
  if (!variant) return null;

  return {
    productId: variant.productId,
    price: variant.price,
    orderable: variant.orderable !== false,
  };
};

