 * identically-named type, same reasoning: `@salesforce/retail-react-app` ships no types for this
 * subpath (falls through `overrides/app/types/vendor.d.ts`'s catch-all ambient `any`), so this
 * documents an assumed shape rather than letting `any` propagate — the real correctness proof is
 * this file's own test comparing against a real `getPriceData` call, not this annotation alone.
 */
type SfccPriceData = {
  /** `findLowestPrice()`'s own `minPrice` — replaces the flat `hit.price` field this mapper used
   *  to read for `currentPrice` (2026-09-08: now sourced from the same call as `originalPrice`,
   *  closing the "two fields could disagree on a multi-variant hit" gap the old code risked). */
  currentPrice: number;
  /** The highest tiered price found — "was" price. `undefined` when the hit has no
   *  `tieredPrices` at all (there is then no maximum to compute). */
  listPrice: number | undefined;
  /** `currentPrice < listPrice` — always `false`, never `true`, when `listPrice` is `undefined`. */
  isOnSale: boolean;
};

/**
 * Derives `currentPrice`/`originalPrice` from a single `getPriceData(hit)` call — ported verbatim
 * from `recentlyViewedFullHistoryCard.ts`'s own `selectPriceFields` (see that file's own docblock
 * for why both fields must come from the one call rather than mixing a flat price field for one
 * and `getPriceData` for the other). No `opts` passed — the default `quantity: 1` is correct for
 * a single-unit card display. No hardcoded fallback currency — if either the price or the
 * currency is absent, formatting is skipped rather than guessed.
 *
 * **Closes 2026-09-08's confirmed gap**: this hit's own `perPricebook: true` + `expand: [...,
 * 'prices']` request (product-list/index.tsx) does carry real tiered pricing — checked directly
 * against a live on-sale product via the Shopper Products detail endpoint (same underlying
 * pricebook data; the search endpoint's own live response couldn't be intercepted directly, since
 * this page's initial data arrives via SSR with no separate client-side request to inspect) —
 * closing the honest "not checked against a live hit" caveat this file's own history carried.
 */
const selectPriceFields = (
  hit: ProductListSearchHit,
  formatPrice: (amount: number, currency: string) => string,
): Pick<ProductListCardResult, 'currentPrice' | 'originalPrice'> => {
  const priceData: SfccPriceData = getPriceData(hit);

  const currentPrice =
    typeof priceData.currentPrice === 'number' && hit.currency
      ? formatPrice(priceData.currentPrice, hit.currency)
      : undefined;

  // Only set when isOnSale is true -- a not-on-sale hit must not render a crossed-out price
  // identical to its current one.
  const originalPrice =
    priceData.isOnSale && typeof priceData.listPrice === 'number' && hit.currency
      ? formatPrice(priceData.listPrice, hit.currency)
      : undefined;

  return { currentPrice, originalPrice };
};

